using System;
using System.Net;
using System.Net.Http.Json;
using System.Threading.Tasks;
using Api.Models.Auth;
using Api.Services;
using Api.Utilities;
using Domain.Entities;
using Infrastructure.Data;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Xunit;
using Moq;
using Domain.Interfaces;
using Microsoft.Extensions.Logging;

namespace Api.Tests
{
    public class AuthEndpointsTests : IClassFixture<TestWebApplicationFactory<Program>>
    {
        private readonly TestWebApplicationFactory<Program> _factory;

        public AuthEndpointsTests(TestWebApplicationFactory<Program> factory)
        {
            _factory = factory;
        }

        [Fact]
        public async Task Register_ValidUser_ReturnsOk()
        {
            // Arrange
            var client = _factory.CreateClient();
            var request = new RegisterRequest("testuser", "test@example.com", "Password123!");

            // Act
            var response = await client.PostAsJsonAsync("/v1/auth/register", request);

            // Assert
            response.EnsureSuccessStatusCode(); // Status Code 200-299
            var authResponse = await response.Content.ReadFromJsonAsync<AuthResponse>();
            Assert.NotNull(authResponse);
            Assert.Equal("testuser", authResponse.Username);
            Assert.NotEmpty(authResponse.Token);
        }

        [Fact]
        public async Task Register_DuplicateUsername_ReturnsBadRequest()
        {
            // Arrange
            var client = _factory.CreateClient();
            var request1 = new RegisterRequest("duplicateuser", "dup1@example.com", "Password123!");
            var request2 = new RegisterRequest("duplicateuser", "dup2@example.com", "Password123!");

            await client.PostAsJsonAsync("/v1/auth/register", request1); // Register first user

            // Act
            var response = await client.PostAsJsonAsync("/v1/auth/register", request2);

            // Assert
            Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);
            var error = await response.Content.ReadFromJsonAsync<dynamic>();
            Assert.Equal("Username already exists.", (string)error!.error);
        }

        [Fact]
        public async Task Register_DuplicateEmail_ReturnsBadRequest()
        {
            // Arrange
            var client = _factory.CreateClient();
            var request1 = new RegisterRequest("user1", "duplicate@example.com", "Password123!");
            var request2 = new RegisterRequest("user2", "duplicate@example.com", "Password123!");

            await client.PostAsJsonAsync("/v1/auth/register", request1); // Register first user

            // Act
            var response = await client.PostAsJsonAsync("/v1/auth/register", request2);

            // Assert
            Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);
            var error = await response.Content.ReadFromJsonAsync<dynamic>();
            Assert.Equal("Email already exists.", (string)error!.error);
        }

        [Fact]
        public async Task Login_ValidCredentials_ReturnsOk()
        {
            // Arrange
            var client = _factory.CreateClient();
            var registerRequest = new RegisterRequest("loginuser", "login@example.com", "Password123!");
            await client.PostAsJsonAsync("/v1/auth/register", registerRequest);

            var loginRequest = new LoginRequest("loginuser", "Password123!");

            // Act
            var response = await client.PostAsJsonAsync("/v1/auth/login", loginRequest);

            // Assert
            response.EnsureSuccessStatusCode();
            var authResponse = await response.Content.ReadFromJsonAsync<AuthResponse>();
            Assert.NotNull(authResponse);
            Assert.Equal("loginuser", authResponse.Username);
            Assert.NotEmpty(authResponse.Token);
        }

        [Fact]
        public async Task Login_InvalidCredentials_ReturnsUnauthorized()
        {
            // Arrange
            var client = _factory.CreateClient();
            var loginRequest = new LoginRequest("nonexistent", "wrongpassword");

            // Act
            var response = await client.PostAsJsonAsync("/v1/auth/login", loginRequest);

            // Assert
            Assert.Equal(HttpStatusCode.Unauthorized, response.StatusCode);
            var error = await response.Content.ReadFromJsonAsync<dynamic>();
            Assert.Equal("Invalid username or password.", (string)error!.error);
        }
    }
}

