import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import TodoForm from './TodoForm';
import { Todo } from '../types/todo';

describe('TodoForm', () => {
  const mockOnSubmit = jest.fn();
  const mockOnCancel = jest.fn();

  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('renders with empty fields in add mode', () => {
    render(<TodoForm onSubmit={mockOnSubmit} />);
    expect(screen.getByLabelText(/Title:/i)).toHaveValue('');
    expect(screen.getByLabelText(/Description:/i)).toHaveValue('');
    expect(screen.queryByLabelText(/Completed/i)).not.toBeInTheDocument();
    expect(screen.getByRole('button', { name: /Add Todo/i })).toBeInTheDocument();
  });

  it('renders with initial values in edit mode', () => {
    const initialTodo: Todo = {
      id: '1',
      title: 'Edit Me',
      description: 'Description to edit',
      completed: true,
    };
    render(<TodoForm initialTodo={initialTodo} onSubmit={mockOnSubmit} isEditMode={true} />);
    expect(screen.getByLabelText(/Title:/i)).toHaveValue('Edit Me');
    expect(screen.getByLabelText(/Description:/i)).toHaveValue('Description to edit');
    expect(screen.getByLabelText(/Completed/i)).toBeChecked();
    expect(screen.getByRole('button', { name: /Update Todo/i })).toBeInTheDocument();
  });

  it('calls onSubmit with correct payload in add mode', async () => {
    render(<TodoForm onSubmit={mockOnSubmit} />);
    fireEvent.change(screen.getByLabelText(/Title:/i), { target: { value: 'New Todo' } });
    fireEvent.change(screen.getByLabelText(/Description:/i), { target: { value: 'New Description' } });
    fireEvent.click(screen.getByRole('button', { name: /Add Todo/i }));

    await waitFor(() => {
      expect(mockOnSubmit).toHaveBeenCalledWith({
        title: 'New Todo',
        description: 'New Description',
      });
    });
    expect(screen.getByLabelText(/Title:/i)).toHaveValue('');
    expect(screen.getByLabelText(/Description:/i)).toHaveValue('');
  });

  it('calls onSubmit with correct payload in edit mode', async () => {
    const initialTodo: Todo = {
      id: '1',
      title: 'Edit Me',
      description: 'Description to edit',
      completed: false,
    };
    render(<TodoForm initialTodo={initialTodo} onSubmit={mockOnSubmit} isEditMode={true} />);
    fireEvent.change(screen.getByLabelText(/Title:/i), { target: { value: 'Updated Title' } });
    fireEvent.click(screen.getByLabelText(/Completed/i)); // Mark as completed
    fireEvent.click(screen.getByRole('button', { name: /Update Todo/i }));

    await waitFor(() => {
      expect(mockOnSubmit).toHaveBeenCalledWith({
        title: 'Updated Title',
        description: 'Description to edit',
        completed: true,
      });
    });
  });

  it('shows error if title is empty', async () => {
    render(<TodoForm onSubmit={mockOnSubmit} />);
    fireEvent.click(screen.getByRole('button', { name: /Add Todo/i }));

    await waitFor(() => {
      expect(screen.getByText(/Title cannot be empty./i)).toBeInTheDocument();
    });
    expect(mockOnSubmit).not.toHaveBeenCalled();
  });

  it('calls onCancel when cancel button is clicked', () => {
    render(<TodoForm onSubmit={mockOnSubmit} onCancel={mockOnCancel} isEditMode={true} />);
    fireEvent.click(screen.getByRole('button', { name: /Cancel/i }));
    expect(mockOnCancel).toHaveBeenCalledTimes(1);
  });

  it('disables buttons while submitting', async () => {
    mockOnSubmit.mockImplementationOnce(() => new Promise(resolve => setTimeout(resolve, 100)));
    render(<TodoForm onSubmit={mockOnSubmit} />);
    fireEvent.change(screen.getByLabelText(/Title:/i), { target: { value: 'New Todo' } });
    fireEvent.click(screen.getByRole('button', { name: /Add Todo/i }));

    expect(screen.getByRole('button', { name: /Saving.../i })).toBeDisabled();
    expect(screen.getByLabelText(/Title:/i)).toBeDisabled();
    expect(screen.getByLabelText(/Description:/i)).toBeDisabled();

    await waitFor(() => expect(screen.getByRole('button', { name: /Add Todo/i })).not.toBeDisabled());
  });
});

