import React, { createContext, useState, useEffect, ReactNode } from 'react';
import { AuthResponse, User } from '../types';
import { login as apiLogin, register as apiRegister } from '../services/auth';

interface AuthContextType {
  isAuthenticated: boolean;
  user: User | null;
  token: string | null;
  login: (email: string, password: string) => Promise<void>;
  register: (email: string, password: string) => Promise<void>;
  logout: () => void;
  loading: boolean;
  error: string | null;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

interface AuthProviderProps {
  children: ReactNode;
}

export const AuthProvider = ({ children }: AuthProviderProps) => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [user, setUser] = useState<User | null>(null);
  const [token, setToken] = useState<string | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const storedToken = localStorage.getItem('jwt_token');
    if (storedToken) {
      setToken(storedToken);
      setIsAuthenticated(true);
      // In a real app, you'd decode the token or make an API call to get user info
      // For simplicity, we'll just set a dummy user for now if token exists
      setUser({ id: 'dummy-id', email: 'user@example.com' });
    }
    setLoading(false);
  }, []);

  const handleAuthSuccess = (authResponse: AuthResponse, email: string) => {
    localStorage.setItem('jwt_token', authResponse.access_token);
    setToken(authResponse.access_token);
    setIsAuthenticated(true);
    setUser({ id: 'some-id', email: email }); // Placeholder user
    setError(null);
  };

  const login = async (email: string, password: string) => {
    setLoading(true);
    setError(null);
    try {
      const response = await apiLogin({ email, password });
      handleAuthSuccess(response.data, email);
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Login failed');
      throw err;
    } finally {
      setLoading(false);
    }
  };

  const register = async (email: string, password: string) => {
    setLoading(true);
    setError(null);
    try {
      const response = await apiRegister({ email, password });
      handleAuthSuccess(response.data, email);
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Registration failed');
      throw err;
    } finally {
      setLoading(false);
    }
  };

  const logout = () => {
    localStorage.removeItem('jwt_token');
    setToken(null);
    setIsAuthenticated(false);
    setUser(null);
    setError(null);
  };

  return (
    <AuthContext.Provider value={{ isAuthenticated, user, token, login, register, logout, loading, error }}>
      {children}
    </AuthContext.Provider>
  );
};

export default AuthContext;

using Microsoft.EntityFrameworkCore;
using Api.Data;
using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.AspNetCore.Authorization; // Added for authorization

namespace Api.Features.Todos;

/// <summary>
/// Provides extension methods to map Todo-related API endpoints.
/// </summary>
public static class TodoEndpoints
{
    public static IEndpointRouteBuilder MapTodoEndpoints(this IEndpointRouteBuilder app)
    {
        var todosApi = app.MapGroup("/api/v1/todos")
            .WithTags("Todos")
            .RequireAuthorization(); // Example: Requires authentication for all endpoints in this group

        // Further authorization logic would be needed within endpoints, e.g., checking UserId

        // GET /api/v1/todos
        todosApi.MapGet("/", async (
            IDbContextFactory<AppDbContext> dbContextFactory,
            bool? completed = null) =>
        {
            using var dbContext = dbContextFactory.CreateDbContext();
            var query = dbContext.Todos.AsQueryable();

            if (completed.HasValue)
            {
                query = query.Where(t => t.Completed == completed.Value);
            }

            var todos = await query
                .OrderBy(t => t.CreatedAt)
                .Select(t => new TodoResponse(t.Id, t.Title, t.Description, t.Completed, t.CreatedAt, t.UpdatedAt))
                .ToListAsync();

            return TypedResults.Ok(todos);
        })
        .WithName("GetAllTodos")
        .WithOpenApi();

        // GET /api/v1/todos/{id}
        todosApi.MapGet("/{id:guid}", async (Guid id, IDbContextFactory<AppDbContext> dbContextFactory) =>
        {
            using var dbContext = dbContextFactory.CreateDbContext();
            var todo = await dbContext.Todos.FindAsync(id);

            return todo is null
                ? TypedResults.NotFound()
                : TypedResults.Ok(new TodoResponse(todo.Id, todo.Title, todo.Description, todo.Completed, todo.CreatedAt, todo.UpdatedAt));
        })
        .WithName("GetTodoById")
        .WithOpenApi();

        // POST /api/v1/todos
        todosApi.MapPost("/", async (CreateTodoRequest request, IDbContextFactory<AppDbContext> dbContextFactory) =>
        {
            using var dbContext = dbContextFactory.CreateDbContext();
            var now = DateTimeOffset.UtcNow;
            var todo = new Todo
            {
                Id = Guid.NewGuid(),
                Title = request.Title,
                Description = request.Description,
                Completed = request.Completed,
                CreatedAt = now,
                UpdatedAt = now
            };

            dbContext.Todos.Add(todo);
            await dbContext.SaveChangesAsync();

            var todoResponse = new TodoResponse(todo.Id, todo.Title, todo.Description, todo.Completed, todo.CreatedAt, todo.UpdatedAt);
            return TypedResults.CreatedAtRoute(todoResponse, "GetTodoById", new { id = todo.Id });
        })
        .WithName("CreateTodo")
        .WithOpenApi();

        // PUT /api/v1/todos/{id}
        todosApi.MapPut("/{id:guid}", async (Guid id, UpdateTodoRequest request, IDbContextFactory<AppDbContext> dbContextFactory) =>
        {
            using var dbContext = dbContextFactory.CreateDbContext();
            var todo = await dbContext.Todos.FindAsync(id);

            if (todo is null)
            {
                return TypedResults.NotFound();
            }

            todo.Title = request.Title ?? todo.Title;
            todo.Description = request.Description ?? todo.Description;
            todo.Completed = request.Completed ?? todo.Completed;
            todo.UpdatedAt = DateTimeOffset.UtcNow;

            await dbContext.SaveChangesAsync();

            return TypedResults.NoContent();
        })
        .WithName("UpdateTodo")
        .WithOpenApi();

        // DELETE /api/v1/todos/{id}
        todosApi.MapDelete("/{id:guid}", async (Guid id, IDbContextFactory<AppDbContext> dbContextFactory) =>
        {
            using var dbContext = dbContextFactory.CreateDbContext();
            var todo = await dbContext.Todos.FindAsync(id);

            if (todo is null)
            {
                return TypedResults.NotFound();
            }

            dbContext.Todos.Remove(todo);
            await dbContext.SaveChangesAsync();

            return TypedResults.NoContent();
        })
        .WithName("DeleteTodo")
        .WithOpenApi();

        return app;
    }
}

from datetime import datetime, timedelta, timezone
from typing import Optional
from passlib.context import CryptContext
from jose import JWTError, jwt

from src.config import settings
from src.schemas.auth import TokenData
from src.exceptions import InvalidCredentialsException

pwd_context = CryptContext(schemes=["bcrypt"], deprecated="auto")

def verify_password(plain_password: str, hashed_password: str) -> bool:
    """Verify a plain password against a hashed password."""
    return pwd_context.verify(plain_password, hashed_password)

def get_password_hash(password: str) -> str:
    """Hash a password."""
    return pwd_context.hash(password)

def create_access_token(data: dict, expires_delta: Optional[timedelta] = None) -> str:
    """Create a JWT access token."""
    to_encode = data.copy()
    if expires_delta:
        expire = datetime.now(timezone.utc) + expires_delta
    else:
        expire = datetime.now(timezone.utc) + timedelta(minutes=settings.access_token_expire_minutes)
    to_encode.update({"exp": expire})
    encoded_jwt = jwt.encode(to_encode, settings.secret_key, algorithm=settings.algorithm)
    return encoded_jwt

def decode_access_token(token: str) -> TokenData:
    """Decode and validate a JWT access token."""
    try:
        payload = jwt.decode(token, settings.secret_key, algorithms=[settings.algorithm])
        user_id: str = payload.get("sub")
        if user_id is None:
            raise InvalidCredentialsException()
        token_data = TokenData(user_id=user_id)
    except JWTError:
        raise InvalidCredentialsException()
    return token_data

