import React, { useState, useEffect } from 'react';
import { ITodo } from '../types/Todo';
import './TodoForm.css';

interface TodoFormProps {
  initialTodo?: ITodo;
  onSubmit: (todo: Omit<ITodo, 'id' | 'createdAt' | 'updatedAt'> | Partial<Omit<ITodo, 'createdAt' | 'updatedAt'>>) => void;
  onCancel?: () => void;
  isEditMode?: boolean;
}

const TodoForm: React.FC<TodoFormProps> = ({
  initialTodo,
  onSubmit,
  onCancel,
  isEditMode = false,
}) => {
  const [title, setTitle] = useState(initialTodo?.title || '');
  const [description, setDescription] = useState(initialTodo?.description || '');
  const [completed, setCompleted] = useState(initialTodo?.completed || false);

  useEffect(() => {
    if (initialTodo) {
      setTitle(initialTodo.title);
      setDescription(initialTodo.description);
      setCompleted(initialTodo.completed);
    } else {
      setTitle('');
      setDescription('');
      setCompleted(false);
    }
  }, [initialTodo]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) {
      // alert('Title cannot be empty.'); // F-009: Replaced alert with console.warn for better UX
      console.warn('Title cannot be empty.');
      return;
    }
    onSubmit({ title, description, completed });
    if (!isEditMode) {
      setTitle('');
      setDescription('');
      setCompleted(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="todo-form">
      <div className="form-group">
        <label htmlFor="title">Title:</label>
        <input
          type="text"
          id="title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          required
          className="form-input"
        />
      </div>
      <div className="form-group">
        <label htmlFor="description">Description:</label>
        <textarea
          id="description"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          rows={4}
          className="form-textarea"
        ></textarea>
      </div>
      {isEditMode && (
        <div className="form-group checkbox-group">
          <input
            type="checkbox"
            id="completed"
            checked={completed}
            onChange={(e) => setCompleted(e.target.checked)}
            className="form-checkbox"
          />
          <label htmlFor="completed">Completed</label>
        </div>
      )}
      <div className="form-actions">
        <button type="submit" className="button primary-button">
          {isEditMode ? 'Update Todo' : 'Add Todo'}
        </button>
        {onCancel && (
          <button type="button" onClick={onCancel} className="button secondary-button">
            Cancel
          </button>
        )}
      </div>
    </form>
  );
};

export default TodoForm;

