using Microsoft.EntityFrameworkCore;
using Api.Data;
using Microsoft.AspNetCore.Http.HttpResults;

namespace Api.Features.Todos;

/// <summary>
/// Provides extension methods to map Todo-related API endpoints.
/// </summary>
public static class TodoEndpoints
{
    public static IEndpointRouteBuilder MapTodoEndpoints(this IEndpointRouteBuilder app)
    {
        var todosApi = app.MapGroup("/api/v1/todos")
            .WithTags("Todos")
            .RequireAuthorization(); // F-001: Added for basic authorization enforcement

        // GET /api/v1/todos
        todosApi.MapGet("/", async (
            IDbContextFactory<AppDbContext> dbContextFactory,
            bool? completed = null) =>
        {
            using var dbContext = dbContextFactory.CreateDbContext();
            var query = dbContext.Todos.AsQueryable();

            if (completed.HasValue)
            {
                query = query.Where(t => t.Completed == completed.Value);
            }

            var todos = await query
                .OrderBy(t => t.CreatedAt) // F-002: Backend always sorts by CreatedAt, sortBy/sortOrder removed from frontend
                .Select(t => new TodoResponse(t.Id, t.Title, t.Description, t.Completed, t.CreatedAt, t.UpdatedAt))
                .ToListAsync();

            return TypedResults.Ok(todos);
        })
        .WithName("GetAllTodos")
        .WithOpenApi();

        // GET /api/v1/todos/{id}
        todosApi.MapGet("/{id:guid}", async (Guid id, IDbContextFactory<AppDbContext> dbContextFactory) =>
        {
            using var dbContext = dbContextFactory.CreateDbContext();
            var todo = await dbContext.Todos.FindAsync(id);

            return todo is null
                ? TypedResults.NotFound()
                : TypedResults.Ok(new TodoResponse(todo.Id, todo.Title, todo.Description, todo.Completed, todo.CreatedAt, todo.UpdatedAt));
        })
        .WithName("GetTodoById")
        .WithOpenApi();

        // POST /api/v1/todos
        todosApi.MapPost("/", async (CreateTodoRequest request, IDbContextFactory<AppDbContext> dbContextFactory) =>
        {
            using var dbContext = dbContextFactory.CreateDbContext();
            var now = DateTimeOffset.UtcNow;
            var todo = new Todo
            {
                // Id = Guid.NewGuid(), // F-010: Removed, Id is generated by the database (NEWID())
                Title = request.Title,
                Description = request.Description,
                Completed = request.Completed,
                CreatedAt = now,
                UpdatedAt = now
            };

            dbContext.Todos.Add(todo);
            await dbContext.SaveChangesAsync();

            var todoResponse = new TodoResponse(todo.Id, todo.Title, todo.Description, todo.Completed, todo.CreatedAt, todo.UpdatedAt);
            return TypedResults.CreatedAtRoute(todoResponse, "GetTodoById", new { id = todo.Id });
        })
        .WithName("CreateTodo")
        .WithOpenApi();

        // PUT /api/v1/todos/{id}
        todosApi.MapPut("/{id:guid}", async (Guid id, UpdateTodoRequest request, IDbContextFactory<AppDbContext> dbContextFactory) =>
        {
            using var dbContext = dbContextFactory.CreateDbContext();
            var todo = await dbContext.Todos.FindAsync(id);

            if (todo is null)
            {
                return TypedResults.NotFound();
            }

            todo.Title = request.Title ?? todo.Title;
            todo.Description = request.Description ?? todo.Description;
            todo.Completed = request.Completed ?? todo.Completed;
            todo.UpdatedAt = DateTimeOffset.UtcNow;

            await dbContext.SaveChangesAsync();

            return TypedResults.NoContent();
        })
        .WithName("UpdateTodo")
        .WithOpenApi();

        // DELETE /api/v1/todos/{id}
        todosApi.MapDelete("/{id:guid}", async (Guid id, IDbContextFactory<AppDbContext> dbContextFactory) =>
        {
            using var dbContext = dbContextFactory.CreateDbContext();
            var todo = await dbContext.Todos.FindAsync(id);

            if (todo is null)
            {
                return TypedResults.NotFound();
            }

            dbContext.Todos.Remove(todo);
            await dbContext.SaveChangesAsync();

            return TypedResults.NoContent();
        })
        .WithName("DeleteTodo")
        .WithOpenApi();

        return app;
    }
}

from fastapi import HTTPException, status

class UserAlreadyExistsException(HTTPException):
    """Custom exception for when a user with the given email already exists."""
    def __init__(self):
        super().__init__(
            status_code=status.HTTP_409_CONFLICT,
            detail="User with this email already exists"
        )

class InvalidCredentialsException(HTTPException):
    """Custom exception for invalid authentication credentials."""
    def __init__(self):
        super().__init__(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Could not validate credentials",
            headers={"WWW-Authenticate": "Bearer"},
        )

class UserNotFoundException(HTTPException):
    """Custom exception for when a user is not found."""
    def __init__(self):
        super().__init__(
            status_code=status.HTTP_404_NOT_FOUND,
            detail="User not found"
        )

class TodoNotFoundException(HTTPException):
    """Custom exception for when a todo item is not found."""
    def __init__(self):
        super().__init__(
            status_code=status.HTTP_404_NOT_FOUND,
            detail="Todo item not found"
        )

class ForbiddenException(HTTPException):
    """Custom exception for forbidden access."""
    def __init__(self):
        super().__init__(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="Not authorized to access this resource"
        )

import { Todo, CreateTodoPayload, UpdateTodoPayload } from '../types/todo';

const API_BASE_URL = '/api/v1/todos';

const handleApiResponse = async (response: Response): Promise<any> => {
  if (!response.ok) {
    let errorMessage = `Failed to fetch todos: ${response.statusText}`;
    try {
      const errorBody = await response.json();
      if (errorBody && errorBody.detail) {
        errorMessage = errorBody.detail; // Assuming backend returns { detail: '...' }
      } else if (errorBody && errorBody.errors) {
        errorMessage = JSON.stringify(errorBody.errors); // Assuming validation errors
      }
    } catch (e) {
      // Ignore if response body is not JSON
    }
    throw new Error(errorMessage);
  }
  return response.json();
};

export const getTodos = async (completed?: boolean): Promise<Todo[]> => {
  const url = completed !== undefined ? `${API_BASE_URL}?completed=${completed}` : API_BASE_URL;
  const response = await fetch(url);
  return handleApiResponse(response);
};

export const getTodoById = async (id: string): Promise<Todo> => {
  const response = await fetch(`${API_BASE_URL}/${id}`);
  return handleApiResponse(response);
};

export const createTodo = async (payload: CreateTodoPayload): Promise<Todo> => {
  const response = await fetch(API_BASE_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(payload),
  });
  return handleApiResponse(response);
};

export const updateTodo = async (id: string, payload: UpdateTodoPayload): Promise<Todo> => {
  const response = await fetch(`${API_BASE_URL}/${id}`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(payload),
  });
  return handleApiResponse(response);
};

export const deleteTodo = async (id: string): Promise<void> => {
  const response = await fetch(`${API_BASE_URL}/${id}`, {
    method: 'DELETE',
  });
  if (!response.ok) {
    let errorMessage = `Failed to delete todo with ID ${id}: ${response.statusText}`;
    try {
      const errorBody = await response.json();
      if (errorBody && errorBody.detail) {
        errorMessage = errorBody.detail;
      } else if (errorBody && errorBody.errors) {
        errorMessage = JSON.stringify(errorBody.errors);
      }
    } catch (e) {
      // Ignore if response body is not JSON
    }
    throw new Error(errorMessage);
  }
};

