using Api.Models.Auth;
using FluentAssertions;
using Microsoft.AspNetCore.Mvc.Testing;
using System.Net;
using System.Net.Http.Json;
using System.Threading.Tasks;
using Xunit;
using Api; // Assuming Program is in Api namespace

namespace IntegrationTests
{
    public class AuthEndpointsIntegrationTests : IClassFixture<CustomWebApplicationFactory<Program>>
    {
        private readonly HttpClient _client;

        public AuthEndpointsIntegrationTests(CustomWebApplicationFactory<Program> factory)
        {
            _client = factory.CreateClient();
        }

        [Fact]
        public async Task Register_ShouldReturnOk_WhenValidRequest()
        {
            // Arrange
            var request = new RegisterRequest(TestConstants.TestUserEmail, TestConstants.TestUserPassword);

            // Act
            var response = await _client.PostAsJsonAsync("/v1/auth/register", request);

            // Assert
            response.Should().HaveStatusCode(HttpStatusCode.OK);
            var authTokens = await response.Content.ReadFromJsonAsync<AuthTokens>();
            authTokens.Should().NotBeNull();
            authTokens!.AccessToken.Should().NotBeNullOrEmpty();
        }

        [Fact]
        public async Task Register_ShouldReturnBadRequest_WhenEmailAlreadyExists()
        {
            // Arrange
            // Register once
            var initialRequest = new RegisterRequest(TestConstants.TestUserEmail, TestConstants.TestUserPassword);
            await _client.PostAsJsonAsync("/v1/auth/register", initialRequest);

            // Attempt to register again with the same email
            var duplicateRequest = new RegisterRequest(TestConstants.TestUserEmail, TestConstants.TestUserPassword);

            // Act
            var response = await _client.PostAsJsonAsync("/v1/auth/register", duplicateRequest);

            // Assert
            response.Should().HaveStatusCode(HttpStatusCode.BadRequest);
            var error = await response.Content.ReadFromJsonAsync<dynamic>();
            ((string)error!.error).Should().Contain("Email already registered");
        }

        [Fact]
        public async Task Login_ShouldReturnOk_WhenValidCredentials()
        {
            // Arrange
            // Register a user first
            var registerRequest = new RegisterRequest(TestConstants.TestUserEmail, TestConstants.TestUserPassword);
            await _client.PostAsJsonAsync("/v1/auth/register", registerRequest);

            var loginRequest = new LoginRequest(TestConstants.TestUserEmail, TestConstants.TestUserPassword);

            // Act
            var response = await _client.PostAsJsonAsync("/v1/auth/login", loginRequest);

            // Assert
            response.Should().HaveStatusCode(HttpStatusCode.OK);
            var authTokens = await response.Content.ReadFromJsonAsync<AuthTokens>();
            authTokens.Should().NotBeNull();
            authTokens!.AccessToken.Should().NotBeNullOrEmpty();
        }

        [Fact]
        public async Task Login_ShouldReturnUnauthorized_WhenInvalidCredentials()
        {
            // Arrange
            // Register a user first
            var registerRequest = new RegisterRequest(TestConstants.TestUserEmail, TestConstants.TestUserPassword);
            await _client.PostAsJsonAsync("/v1/auth/register", registerRequest);

            var loginRequest = new LoginRequest(TestConstants.TestUserEmail, "WrongPassword123!");

            // Act
            var response = await _client.PostAsJsonAsync("/v1/auth/login", loginRequest);

            // Assert
            response.Should().HaveStatusCode(HttpStatusCode.Unauthorized);
            var error = await response.Content.ReadFromJsonAsync<dynamic>();
            ((string)error!.error).Should().Contain("Invalid credentials");
        }

        [Fact]
        public async Task Login_ShouldReturnUnauthorized_WhenUserDoesNotExist()
        {
            // Arrange
            var loginRequest = new LoginRequest("nonexistent@example.com", "Password123!");

            // Act
            var response = await _client.PostAsJsonAsync("/v1/auth/login", loginRequest);

            // Assert
            response.Should().HaveStatusCode(HttpStatusCode.Unauthorized);
            var error = await response.Content.ReadFromJsonAsync<dynamic>();
            ((string)error!.error).Should().Contain("Invalid credentials");
        }
    }
}

import { useState, useEffect, useCallback } from 'react';
import { Todo, CreateTodoPayload, UpdateTodoPayload } from '../types/todo';
import { getTodos, createTodo, updateTodo, deleteTodo } from '../api/todos';

interface UseTodosResult {
  todos: Todo[];
  loading: boolean;
  error: string | null;
  addTodo: (payload: CreateTodoPayload) => Promise<void>;
  updateTodoItem: (id: string, payload: UpdateTodoPayload) => Promise<void>;
  deleteTodoItem: (id: string) => Promise<void>;
  refreshTodos: () => Promise<void>;
}

export const useTodos = (): UseTodosResult => {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  const fetchTodos = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await getTodos();
      setTodos(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchTodos();
  }, [fetchTodos]);

  const addTodo = async (payload: CreateTodoPayload) => {
    try {
      const newTodo = await createTodo(payload);
      setTodos((prevTodos) => [...prevTodos, newTodo]);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to add todo');
      throw err;
    }
  };

  const updateTodoItem = async (id: string, payload: UpdateTodoPayload) => {
    try {
      const updated = await updateTodo(id, payload);
      setTodos((prevTodos) =>
        prevTodos.map((todo) => (todo.id === id ? updated : todo))
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to update todo');
      throw err;
    }
  };

  const deleteTodoItem = async (id: string) => {
    try {
      await deleteTodo(id);
      setTodos((prevTodos) => prevTodos.filter((todo) => todo.id !== id));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to delete todo');
      throw err;
    }
  };

  return {
    todos,
    loading,
    error,
    addTodo,
    updateTodoItem,
    deleteTodoItem,
    refreshTodos: fetchTodos,
  };
};

import React, { useState, useEffect } from 'react';
import { ITodo } from '../types/Todo';
import './TodoForm.css';

interface TodoFormProps {
  initialTodo?: ITodo;
  onSubmit: (todo: Omit<ITodo, 'id'> | Partial<ITodo>) => void;
  onCancel?: () => void;
  isEditMode?: boolean;
}

const TodoForm: React.FC<TodoFormProps> = ({
  initialTodo,
  onSubmit,
  onCancel,
  isEditMode = false,
}) => {
  const [title, setTitle] = useState(initialTodo?.title || '');
  const [description, setDescription] = useState(initialTodo?.description || '');
  const [completed, setCompleted] = useState(initialTodo?.completed || false);

  useEffect(() => {
    if (initialTodo) {
      setTitle(initialTodo.title);
      setDescription(initialTodo.description);
      setCompleted(initialTodo.completed);
    } else {
      setTitle('');
      setDescription('');
      setCompleted(false);
    }
  }, [initialTodo]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) {
      alert('Title cannot be empty.');
      return;
    }
    onSubmit({ title, description, completed });
    if (!isEditMode) {
      setTitle('');
      setDescription('');
      setCompleted(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="todo-form">
      <div className="form-group">
        <label htmlFor="title">Title:</label>
        <input
          type="text"
          id="title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          required
          className="form-input"
        />
      </div>
      <div className="form-group">
        <label htmlFor="description">Description:</label>
        <textarea
          id="description"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          rows={4}
          className="form-textarea"
        ></textarea>
      </div>
      {isEditMode && (
        <div className="form-group checkbox-group">
          <input
            type="checkbox"
            id="completed"
            checked={completed}
            onChange={(e) => setCompleted(e.target.checked)}
            className="form-checkbox"
          />
          <label htmlFor="completed">Completed</label>
        </div>
      )}
      <div className="form-actions">
        <button type="submit" className="button primary-button">
          {isEditMode ? 'Update Todo' : 'Add Todo'}
        </button>
        {onCancel && (
          <button type="button" onClick={onCancel} className="button secondary-button">
            Cancel
          </button>
        )}
      </div>
    </form>
  );
};

export default TodoForm;

