const getCsrfToken = (): string => {
  const meta = document.querySelector('meta[name="csrf-token"]');
  if (meta && meta.getAttribute('content')) {
    return meta.getAttribute('content') as string;
  }
  // Fallback for environments without meta tag (e.g., SSR)
  // In production, this should come from a secure endpoint or cookie
  const token = document.cookie.match(/csrf-token=([^;]+)/)?.[1];
  if (token) return token;
  throw new Error('CSRF token not found - check authentication');
};

