import { Todo } from '../types/todo';

const API_BASE_URL = '/api/v1/todos';

// Placeholder for CSRF token retrieval. In a real app, this would fetch from a meta tag,
// a dedicated endpoint, or be managed by a library.
const getCsrfToken = (): string => {
  // For demonstration, returning a dummy token.
  // In production, ensure this is securely generated and retrieved.
  return 'dummy-csrf-token-for-dev';
};

// Utility function for fetch with timeout
const fetchWithTimeout = async (url: string, options: RequestInit = {}, timeout = 10000): Promise<Response> => {
  const controller = new AbortController();
  const id = setTimeout(() => controller.abort(), timeout);
  try {
    const response = await fetch(url, { ...options, signal: controller.signal });
    clearTimeout(id);
    return response;
  } catch (error) {
    clearTimeout(id);
    throw error;
  }
};

export const getTodos = async (): Promise<Todo[]> => {
  const response = await fetchWithTimeout(API_BASE_URL);
  if (!response.ok) {
    throw new Error(`Failed to fetch todos: ${response.statusText}`);
  }
  return response.json();
};

export const createTodo = async (title: string): Promise<Todo> => {
  const csrfToken = getCsrfToken();
  const response = await fetchWithTimeout(API_BASE_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrfToken, // Include CSRF token
    },
    body: JSON.stringify({ title }),
  });
  if (!response.ok) {
    throw new Error(`Failed to create todo: ${response.statusText}`);
  }
  return response.json();
};

export const completeTodo = async (id: string): Promise<Todo> => {
  const csrfToken = getCsrfToken();
  const response = await fetchWithTimeout(`${API_BASE_URL}/${id}/complete`, {
    method: 'PUT',
    headers: {
      'X-CSRF-Token': csrfToken, // Include CSRF token
    },
  });
  if (!response.ok) {
    throw new Error(`Failed to complete todo: ${response.statusText}`);
  }
  return response.json();
};

