using System.Net;
using System.Net.Http.Json;
using Api.Features.Todos;
using FluentAssertions;
using Xunit;

namespace Api.Tests;

public class TodoEndpointsTests : IClassFixture<TestWebApplicationFactory>
{
    private readonly HttpClient _client;

    public TodoEndpointsTests(TestWebApplicationFactory factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task PostTodo_ReturnsCreatedTodo()
    {
        // Arrange
        var request = new CreateTodoRequest("Buy groceries");

        // Act
        var response = await _client.PostAsJsonAsync("/api/v1/todos", request);

        // Assert
        response.StatusCode.Should().Be(HttpStatusCode.Created);
        var todo = await response.Content.ReadFromJsonAsync<TodoResponse>();
        todo.Should().NotBeNull();
        todo!.Title.Should().Be("Buy groceries");
        todo.Completed.Should().BeFalse();
        todo.Id.Should().NotBeEmpty();
    }

    [Fact]
    public async Task PostTodo_WithEmptyTitle_ReturnsBadRequest()
    {
        // Arrange
        var request = new CreateTodoRequest("");

        // Act
        var response = await _client.PostAsJsonAsync("/api/v1/todos", request);

        // Assert
        response.StatusCode.Should().Be(HttpStatusCode.BadRequest);
        var error = await response.Content.ReadAsStringAsync();
        error.Should().Contain("Title cannot be empty.");
    }

    [Fact]
    public async Task GetAllTodos_ReturnsListOfTodos()
    {
        // Arrange
        await _client.PostAsJsonAsync("/api/v1/todos", new CreateTodoRequest("Task 1"));
        await _client.PostAsJsonAsync("/api/v1/todos", new CreateTodoRequest("Task 2"));

        // Act
        var response = await _client.GetAsync("/api/v1/todos");

        // Assert
        response.StatusCode.Should().Be(HttpStatusCode.OK);
        var todos = await response.Content.ReadFromJsonAsync<List<TodoResponse>>();
        todos.Should().NotBeNull();
        todos!.Count.Should().BeGreaterOrEqualTo(2);
        todos.Should().Contain(t => t.Title == "Task 1");
        todos.Should().Contain(t => t.Title == "Task 2");
    }

    [Fact]
    public async Task CompleteTodo_MarksTodoAsComplete()
    {
        // Arrange
        var createResponse = await _client.PostAsJsonAsync("/api/v1/todos", new CreateTodoRequest("Task to complete"));
        var createdTodo = await createResponse.Content.ReadFromJsonAsync<TodoResponse>();
        createdTodo.Should().NotBeNull();
        createdTodo!.Completed.Should().BeFalse();

        // Act
        var completeResponse = await _client.PutAsync($"/api/v1/todos/{createdTodo.Id}/complete", null);

        // Assert
        completeResponse.StatusCode.Should().Be(HttpStatusCode.OK);
        var completedTodo = await completeResponse.Content.ReadFromJsonAsync<TodoResponse>();
        completedTodo.Should().NotBeNull();
        completedTodo!.Id.Should().Be(createdTodo.Id);
        completedTodo.Title.Should().Be(createdTodo.Title);
        completedTodo.Completed.Should().BeTrue();

        // Verify by getting all todos
        var getResponse = await _client.GetAsync("/api/v1/todos");
        var todos = await getResponse.Content.ReadFromJsonAsync<List<TodoResponse>>();
        todos.Should().Contain(t => t.Id == createdTodo.Id && t.Completed == true);
    }

    [Fact]
    public async Task CompleteTodo_WithNonExistentId_ReturnsNotFound()
    {
        // Arrange
        var nonExistentId = Guid.NewGuid();

        // Act
        var response = await _client.PutAsync($"/api/v1/todos/{nonExistentId}/complete", null);

        // Assert
        response.StatusCode.Should().Be(HttpStatusCode.NotFound);
    }
}

