import { ITodo } from '../types/Todo';

const API_BASE_URL = '/api/v1/todos';

export const getTodos = async (
  completed?: boolean,
  sortBy: string = 'id',
  sortOrder: 'asc' | 'desc' = 'asc'
): Promise<ITodo[]> => {
  const params = new URLSearchParams();
  if (completed !== undefined) {
    params.append('completed', String(completed));
  }
  params.append('sortBy', sortBy);
  params.append('sortOrder', sortOrder);

  const response = await fetch(`${API_BASE_URL}?${params.toString()}`);
  if (!response.ok) {
    throw new Error(`Failed to fetch todos: ${response.statusText}`);
  }
  return response.json();
};

export const getTodo = async (id: string): Promise<ITodo> => {
  const response = await fetch(`${API_BASE_URL}/${id}`);
  if (!response.ok) {
    throw new Error(`Failed to fetch todo with ID ${id}: ${response.statusText}`);
  }
  return response.json();
};

export const createTodo = async (todo: Omit<ITodo, 'id'>): Promise<ITodo> => {
  const response = await fetch(API_BASE_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(todo),
  });
  if (!response.ok) {
    throw new Error(`Failed to create todo: ${response.statusText}`);
  }
  return response.json();
};

export const updateTodo = async (id: string, todo: Partial<ITodo>): Promise<ITodo> => {
  const response = await fetch(`${API_BASE_URL}/${id}`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(todo),
  });
  if (!response.ok) {
    throw new Error(`Failed to update todo with ID ${id}: ${response.statusText}`);
  }
  return response.json();
};

export const deleteTodo = async (id: string): Promise<void> => {
  const response = await fetch(`${API_BASE_URL}/${id}`, {
    method: 'DELETE',
  });
  if (!response.ok) {
    throw new Error(`Failed to delete todo with ID ${id}: ${response.statusText}`);
  }
};

import React from 'react';
import { ActivityEvent, Commit, PullRequest, Issue } from '../types/api';
import './ActivityFeedItem.css';

interface ActivityFeedItemProps {
  event: ActivityEvent;
}

const ActivityFeedItem: React.FC<ActivityFeedItemProps> = ({ event }) => {
  const renderCommit = (commit: Commit) => (
    <>
      <span className="ActivityFeedItem-icon">📝</span>
      <div className="ActivityFeedItem-content">
        <a href={commit.url} target="_blank" rel="noopener noreferrer" className="ActivityFeedItem-title">
          Commit: {commit.message.split('\n')[0]}
        </a>
        <p className="ActivityFeedItem-meta">
          by {commit.author} on {new Date(commit.date).toLocaleString()}
        </p>
      </div>
    </>
  );

  const renderPullRequest = (pr: PullRequest) => (
    <>
      <span className="ActivityFeedItem-icon">
        {pr.state === 'open' ? '🔄' : pr.state === 'merged' ? '✅' : '❌'}
      </span>
      <div className="ActivityFeedItem-content">
        <a href={pr.url} target="_blank" rel="noopener noreferrer" className="ActivityFeedItem-title">
          PR #{pr.number}: {pr.title} ({pr.state})
        </a>
        <p className="ActivityFeedItem-meta">
          by {pr.author} created on {new Date(pr.createdAt).toLocaleString()}
        </p>
      </div>
    </>
  );

  const renderIssue = (issue: Issue) => (
    <>
      <span className="ActivityFeedItem-icon">
        {issue.state === 'open' ? '❗' : '✔️'}
      </span>
      <div className="ActivityFeedItem-content">
        <a href={issue.url} target="_blank" rel="noopener noreferrer" className="ActivityFeedItem-title">
          Issue #{issue.number}: {issue.title} ({issue.state})
        </a>
        <p className="ActivityFeedItem-meta">
          by {issue.author} created on {new Date(issue.createdAt).toLocaleString()}
        </p>
      </div>
    </>
  );

  return (
    <div className="ActivityFeedItem">
      {event.type === 'commit' && renderCommit(event as Commit)}
      {event.type === 'pull_request' && renderPullRequest(event as PullRequest)}
      {event.type === 'issue' && renderIssue(event as Issue)}
    </div>
  );
};

export default ActivityFeedItem;

